@SpringBootTest @Transactional
@Sql({"/db/migration/V42__organization_accounting.sql","/db/migration/V43__country_payroll_accounting.sql","/db/migration/V44__us_payroll_accounting.sql","/db/migration/V46__uk_payroll_accounting.sql"})
class AccountingIntegrationTest {
 @Autowired com.example.demo.base.service.CompanyService companies;@Autowired com.example.demo.base.controller.CompanyController companyController;
 @Autowired AccountingService service;@Autowired AccountingExportService exports;@Autowired AccountingController controller;
 @Autowired EntityManager em;@Autowired JdbcTemplate jdbc;
 Company root,branch,foreign;Organization org;Employee staff,missing,branchStaff;Payslip slip;Deduction pf,tds;
 YearMonth ym=YearMonth.now().minusMonths(1);
 BigDecimal amount(String n){return new BigDecimal(n).setScale(2);}
 @BeforeEach void setup(){
  TenantContext.clear();org=new Organization();org.setName("Accounting fixture "+UUID.randomUUID());org.setSlug("accounting-"+UUID.randomUUID());em.persist(org);
  root=company("Root",org,null,"public","INR");branch=company("Branch",org,root,null,"AED");var other=new Organization();other.setName("Other organization");other.setSlug("other-"+UUID.randomUUID());em.persist(other);foreign=company("Foreign",other,null,"foreign_fixture","INR");
  staff=employee(root,"Salary employee");missing=employee(root,"Missing payslip");branchStaff=employee(branch,"Branch employee");
  pf=new Deduction();pf.setTitle("Employee PF fixture");pf.setCompany(root);em.persist(pf);tds=new Deduction();tds.setTitle("TDS fixture");tds.setCompany(root);em.persist(tds);
  slip=payslip(staff,root,"60000","3000","57000");em.flush();
  slip.setPayHeadData("{\"pretax_deductions\":[{\"deduction_id\":"+pf.getId()+",\"title\":\"PF\",\"amount\":2000,\"employer_contribution_amount\":2000}],\"tax_deductions\":[{\"deduction_id\":"+tds.getId()+",\"title\":\"TDS\",\"amount\":1000}]}");em.flush();
  signIn("ROLE_PLATFORM_SUPER_ADMIN");service.mapDeduction(root.getId(),new AccountingService.MappingRequest(pf.getId(),"PF"));service.mapDeduction(root.getId(),new AccountingService.MappingRequest(tds.getId(),"TDS"));
 }
 Company company(String name,Organization organization,Company parent,String schema,String currency){var c=new Company();c.setName(name+UUID.randomUUID());c.setOrganization(organization);c.setSchemaName(schema);c.setCurrency(currency);c.setCountry("India");if(parent!=null){c.setParentCompany(parent);c.setCompanyType(Company.CompanyType.BRANCH);}em.persist(c);return c;}
 Employee employee(Company company,String name){var e=new Employee();e.setCompany(company);e.setFirstName(name);e.setBadgeId("FIX-"+UUID.randomUUID());em.persist(e);return e;}
 Payslip payslip(Employee e,Company c,String gross,String deduction,String net){var p=new Payslip();p.setCompany(c);p.setEmployee(e);p.setStartDate(ym.atDay(1));p.setEndDate(ym.atEndOfMonth());p.setBasicPay(amount(gross));p.setGrossPay(amount(gross));p.setDeduction(amount(deduction));p.setNetPay(amount(net));p.setStatus(Payslip.PayslipStatus.CONFIRMED);p.setPayHeadData("{}");em.persist(p);return p;}
 void signIn(String role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("fixture-accountant",null,List.of(new SimpleGrantedAuthority(role),new SimpleGrantedAuthority("payroll:view"),new SimpleGrantedAuthority("payroll:approve"))));AccessScopeContext.set(new AccessScopeContext.ScopeData(-1L,null,null,List.of()));CompanyContext.set(root.getId());}
 @AfterEach void clear(){SecurityContextHolder.clearContext();AccessScopeContext.clear();CompanyContext.clear();TenantContext.clear();}
 @SuppressWarnings("unchecked") List<Map<String,Object>> salaryRows(boolean organization){return (List<Map<String,Object>>)service.salary(root.getId(),ym.toString(),organization,null).get("rows");}
 Map<String,Object> salaryRow(){return salaryRows(false).stream().filter(r->Objects.equals(r.get("payslip_id"),slip.getId())).findFirst().orElseThrow();}
 AccountingService.PayrollPostRequest post(String requestKey){return new AccountingService.PayrollPostRequest(ym.toString(),false,List.of(slip.getId()),requestKey,"BANK");}
 AccountingService.JournalRequest expense(String key,String total){return new AccountingService.JournalRequest(key,LocalDate.now(),"EXPENSE","Office expense fixture","REF-EXP",List.of(new AccountingService.Line("GENERAL_EXPENSE",amount(total),amount("0")),new AccountingService.Line("BANK",amount("0"),amount(total))));}
 long entries(){return jdbc.queryForObject("SELECT count(*) FROM public.accounting_entries WHERE organization_id=?",Long.class,org.getId());}
 @Test void salaryExportDoesNotCreateOrWriteChartOfAccounts()throws Exception {
  jdbc.update("DELETE FROM public.accounting_accounts WHERE organization_id=?",org.getId());
  assertThat(exports.salary(root.getId(),ym.toString(),false,null)).isNotEmpty();
  assertThat(jdbc.queryForObject("SELECT count(*) FROM public.accounting_accounts WHERE organization_id=?",Long.class,org.getId())).isZero();
 }
 @Test void salaryReadsActualAmountsAndShowsMissingEmployees(){var row=salaryRow();assertThat(row.get("pf")).isEqualTo(amount("2000"));assertThat(row.get("tds")).isEqualTo(amount("1000"));assertThat(row.get("employer_pf")).isEqualTo(amount("2000"));assertThat(row.get("total_cost")).isEqualTo(amount("62000"));assertThat(row.get("classified")).isEqualTo(true);assertThat(salaryRows(false)).hasSize(2);assertThat(salaryRows(false)).anySatisfy(r->assertThat(r.get("status")).isEqualTo("MISSING"));}
 @Test void archivedAndTransferredEmployeeHistoryIsKept(){staff.setActive(false);staff.setCompany(branch);em.flush();assertThat(salaryRow().get("gross_pay")).isEqualTo(amount("60000"));}
 @Test void organizationReportsKeepCurrenciesSeparate(){payslip(branchStaff,branch,"5000","0","5000");em.flush();var data=service.salary(root.getId(),ym.toString(),true,null);assertThat((Map<String,?>)data.get("totals")).containsKeys("INR","AED");assertThat(salaryRows(false)).noneSatisfy(row->assertThat(row.get("company_id")).isEqualTo(branch.getId()));}
 @Test void unclassifiedPayrollCannotPostUntilReviewed(){jdbc.update("DELETE FROM public.accounting_deduction_categories WHERE company_id=?",root.getId());assertThat(salaryRow().get("classified")).isEqualTo(false);assertThatThrownBy(()->service.postPayroll(root.getId(),post("unclassified"))).hasMessageContaining("classifications");assertThat(entries()).isZero();service.reviewPayroll(root.getId(),slip.getId(),new AccountingService.ReviewRequest(amount("2000"),amount("1000"),amount("2000"),amount("0"),amount("0"),amount("0"),amount("0"),"Verified salary register fixture"));assertThat(salaryRow().get("classified")).isEqualTo(true);service.postPayroll(root.getId(),post("reviewed"));assertThat(entries()).isEqualTo(1);}
 @Test void confirmedPayrollPostsBalancedAndIsIdempotent(){service.postPayroll(root.getId(),post("payroll-one"));service.postPayroll(root.getId(),post("payroll-two"));assertThat(entries()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT sum(debit-credit) FROM public.accounting_lines l JOIN public.accounting_entries e ON e.id=l.entry_id WHERE e.company_id=?",BigDecimal.class,root.getId())).isEqualByComparingTo("0");assertThat(salaryRow().get("payroll_posted")).isEqualTo(true);}
 @Test void draftPayrollCannotPost(){slip.setStatus(Payslip.PayslipStatus.DRAFT);em.flush();assertThatThrownBy(()->service.postPayroll(root.getId(),post("draft"))).hasMessageContaining("approved");assertThat(entries()).isZero();}
 @Test void changedPostedPayrollRequiresReversal(){service.postPayroll(root.getId(),post("first"));slip.setGrossPay(amount("61000"));slip.setNetPay(amount("58000"));em.flush();assertThat(salaryRow().get("payroll_posted")).isEqualTo(false);assertThatThrownBy(()->service.postPayroll(root.getId(),post("changed"))).hasMessageContaining("changed after posting");assertThat(entries()).isEqualTo(1);}
 @Test void paymentRecordsBothWorkflowAndJournalAndRetryIsSafe(){var request=new AccountingService.PaymentRequest(slip.getId(),"BANK-FIXTURE",ym.atEndOfMonth(),"BANK","payment-one");service.recordPayment(root.getId(),request);service.recordPayment(root.getId(),request);em.refresh(slip);assertThat(slip.getStatus()).isEqualTo(Payslip.PayslipStatus.PAID);assertThat(slip.getPaymentReference()).isEqualTo("BANK-FIXTURE");assertThat(entries()).isEqualTo(2);assertThat(salaryRow().get("payment_posted")).isEqualTo(true);assertThatThrownBy(()->service.recordPayment(root.getId(),new AccountingService.PaymentRequest(slip.getId(),"BANK-FIXTURE",ym.atEndOfMonth(),"CASH","payment-one"))).hasMessageContaining("different account");}
 @Test void salaryPaymentRequiresReferenceAndApprovedStatus(){assertThatThrownBy(()->service.recordPayment(root.getId(),new AccountingService.PaymentRequest(slip.getId(),"",LocalDate.now(),"BANK","no-ref"))).hasMessageContaining("reference");slip.setStatus(Payslip.PayslipStatus.DRAFT);em.flush();assertThatThrownBy(()->service.recordPayment(root.getId(),new AccountingService.PaymentRequest(slip.getId(),"REF",LocalDate.now(),"BANK","draft-payment"))).hasMessageContaining("approved");assertThat(entries()).isZero();}
 @Test void paidSourceWithoutPaymentDateCannotBeBookedAsCash(){slip.setStatus(Payslip.PayslipStatus.PAID);em.flush();assertThatThrownBy(()->service.postPayroll(root.getId(),post("missing-date"))).hasMessageContaining("payment date");}
 @Test void journalIsBalancedAndRetainsHistoryThroughReversal(){long id=service.journal(root.getId(),expense("expense-one","1000"));assertThat(service.journal(root.getId(),expense("expense-one","1000"))).isEqualTo(id);assertThatThrownBy(()->service.journal(root.getId(),expense("expense-one","2000"))).hasMessageContaining("different entry");long reverse=service.reverse(root.getId(),id,new AccountingService.ReverseRequest("Correction fixture",LocalDate.now(),"reverse-one"));assertThat(service.reverse(root.getId(),id,new AccountingService.ReverseRequest("Retry fixture",LocalDate.now(),"reverse-two"))).isEqualTo(reverse);assertThat(entries()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT sum(l.debit-l.credit) FROM public.accounting_lines l JOIN public.accounting_entries e ON e.id=l.entry_id WHERE e.company_id=? AND l.account_code='GENERAL_EXPENSE'",BigDecimal.class,root.getId())).isEqualByComparingTo("0");}
 @Test void reversalRetainsOriginalCurrencyAfterCompanyCurrencyChanges(){
  long id=service.journal(root.getId(),expense("currency-original","1000"));root.setCurrency("AED");em.flush();
  long reversal=service.reverse(root.getId(),id,new AccountingService.ReverseRequest("Currency correction fixture",LocalDate.now(),"currency-reverse"));
  assertThat(jdbc.queryForObject("SELECT currency FROM public.accounting_entries WHERE id=?",String.class,reversal)).isEqualTo("INR");
  assertThat(jdbc.queryForObject("SELECT sum(l.debit-l.credit) FROM public.accounting_lines l JOIN public.accounting_entries e ON e.id=l.entry_id WHERE e.company_id=? AND e.currency='INR' AND l.account_code='GENERAL_EXPENSE'",BigDecimal.class,root.getId())).isEqualByComparingTo("0");
 }
 @Test void invalidJournalAmountsAndAccountsAreRejected(){var bad=new AccountingService.JournalRequest("unbalanced",LocalDate.now(),"JOURNAL","Fixture",null,List.of(new AccountingService.Line("GENERAL_EXPENSE",amount("10"),amount("0")),new AccountingService.Line("BANK",amount("0"),amount("9"))));assertThatThrownBy(()->service.journal(root.getId(),bad)).hasMessageContaining("balance");var missing=new AccountingService.JournalRequest("unknown",LocalDate.now(),"JOURNAL","Fixture",null,List.of(new AccountingService.Line("UNKNOWN",amount("10"),amount("0")),new AccountingService.Line("BANK",amount("0"),amount("10"))));assertThatThrownBy(()->service.journal(root.getId(),missing)).hasMessageContaining("Unknown account");assertThat(entries()).isZero();}
 @Test void accountsAndProfitReportsAreFunctional(){service.createAccount(root.getId(),"RENT","Office rent","EXPENSE");assertThat(service.accounts(root.getId())).anySatisfy(account->assertThat(account.get("code")).isEqualTo("RENT"));service.journal(root.getId(),expense("profit-expense","1000"));service.journal(root.getId(),new AccountingService.JournalRequest("income",LocalDate.now(),"INCOME","Income fixture","INV-1",List.of(new AccountingService.Line("BANK",amount("2500"),amount("0")),new AccountingService.Line("INCOME",amount("0"),amount("2500")))));var data=service.ledger(root.getId(),YearMonth.now().toString(),false,0,50);@SuppressWarnings("unchecked")var profit=(List<Map<String,Object>>)data.get("profit_loss");assertThat(profit).hasSize(1);assertThat(profit.getFirst().get("income")).isEqualTo(amount("2500"));assertThat(profit.getFirst().get("expenses")).isEqualTo(amount("1000"));}
 @Test void sourcePayrollReviewCannotBeAlteredAfterPosting(){service.postPayroll(root.getId(),post("posted-review"));assertThatThrownBy(()->service.reviewPayroll(root.getId(),slip.getId(),new AccountingService.ReviewRequest(amount("1000"),amount("2000"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),"Changed classification"))).hasMessageContaining("Reverse");}
 @Test void branchScopeCannotSeeWholeOrganizationOrForeignAccounts(){signIn("ROLE_ACCOUNTANT");AccessScopeContext.set(new AccessScopeContext.ScopeData(1L,root.getId(),UserRole.AccessScope.BRANCH,List.of(root.getId())));assertThatThrownBy(()->service.salary(root.getId(),ym.toString(),true,null)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->service.salary(foreign.getId(),ym.toString(),false,null)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
 @Test void selfScopeAndExcludedPositionsCannotReadAccounts(){signIn("ROLE_EMPLOYEE");AccessScopeContext.set(new AccessScopeContext.ScopeData(1L,root.getId(),UserRole.AccessScope.SELF,List.of(root.getId())));assertThatThrownBy(()->service.salary(root.getId(),ym.toString(),false,null)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);signIn("POSITION_PAYROLL_EXCLUDED");assertThatThrownBy(()->service.accounts(root.getId())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
 @Test void controllerRejectsEmployeeEvenWithPayrollPermission(){signIn("ROLE_EMPLOYEE");assertThatThrownBy(()->controller.journal(root.getId(),expense("employee-write","1000"))).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->controller.salary(root.getId(),ym.toString(),false,null)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
 @Test void payrollAccrualCannotReverseWhilePaymentJournalExists(){service.recordPayment(root.getId(),new AccountingService.PaymentRequest(slip.getId(),"BANK-PAY",ym.atEndOfMonth(),"BANK","paid"));long id=jdbc.queryForObject("SELECT id FROM public.accounting_entries WHERE company_id=? AND type='PAYROLL'",Long.class,root.getId());assertThatThrownBy(()->service.reverse(root.getId(),id,new AccountingService.ReverseRequest("Incorrect payroll",LocalDate.now(),"bad-reversal"))).hasMessageContaining("payment journal");}
 @Test void uaeProfileUsesHeadOfficeCountryAndPostsPensionWithoutIndianTax()throws Exception {
  root.setCountry("United Arab Emirates");root.setCurrency("AED");branch.setCountry("India");slip.setPayHeadData("{\"pretax_deductions\":[{\"deduction_id\":"+pf.getId()+",\"amount\":3000,\"employer_contribution_amount\":2000}]}");em.flush();
  service.mapDeduction(root.getId(),new AccountingService.MappingRequest(pf.getId(),"PENSION"));
  var report=service.salary(branch.getId(),ym.toString(),false,null);assertThat(((AccountingCountryProfile)report.get("country_profile")).code()).isEqualTo("AE");
  var row=salaryRow();assertThat(row.get("pension")).isEqualTo(amount("3000"));assertThat(row.get("tds")).isEqualTo(amount("0"));assertThat(row.get("total_cost")).isEqualTo(amount("62000"));
  service.postPayroll(root.getId(),post("uae-pension"));assertThat(jdbc.queryForObject("SELECT sum(debit-credit) FROM public.accounting_lines l JOIN public.accounting_entries e ON e.id=l.entry_id WHERE e.company_id=?",BigDecimal.class,root.getId())).isEqualByComparingTo("0");
  assertThatThrownBy(()->service.mapDeduction(root.getId(),new AccountingService.MappingRequest(tds.getId(),"TDS"))).hasMessageContaining("country");
  try(var wb=new XSSFWorkbook(new ByteArrayInputStream(exports.salary(root.getId(),ym.toString(),false,null)))){var header=wb.getSheet("Salary register").getRow(0);var labels=new ArrayList<String>();header.forEach(c->labels.add(c.getStringCellValue()));assertThat(labels).contains("Employee pension / contributions","Organization country").doesNotContain("Employee PF","TDS");}
 }
 @Test void countryChangeFlagsExistingIndianAmountsRatherThanSilentlyReclassifying(){root.setCountry("UAE");em.flush();assertThat(salaryRow().get("classified")).isEqualTo(false);assertThatThrownBy(()->service.postPayroll(root.getId(),post("wrong-country"))).hasMessageContaining("classifications");assertThat(entries()).isZero();}
 @Test void missingCountryDoesNotAssumeIndiaOrPermitPayrollPosting(){root.setCountry(null);em.flush();assertThat(((AccountingCountryProfile)service.salary(root.getId(),ym.toString(),false,null).get("country_profile")).code()).isEqualTo("GENERAL");assertThat(salaryRow().get("classified")).isEqualTo(false);assertThatThrownBy(()->service.postPayroll(root.getId(),post("missing-country"))).hasMessageContaining("classifications");}
 @Test void otherCountryUsesNeutralProfileAndManualPensionReview(){root.setCountry("Singapore");slip.setPayHeadData("{}");em.flush();service.reviewPayroll(root.getId(),slip.getId(),new AccountingService.ReviewRequest(amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),"Reviewed local contributions",amount("3000"),amount("2000")));assertThat(salaryRow().get("classified")).isEqualTo(true);service.postPayroll(root.getId(),post("generic-contributions"));assertThat(entries()).isEqualTo(1);}
 @Test void usPayrollPostsSeparateWithholdingAndEmployerTaxAccounts()throws Exception {
  root.setCountry("United States");root.setCurrency("USD");slip.setGrossPay(amount("10000"));slip.setDeduction(amount("2500"));slip.setNetPay(amount("7500"));slip.setPayHeadData("{}");em.flush();
  var taxes=Map.of("federal",amount("1000"),"state",amount("500"),"local",amount("100"),"social_security",amount("700"),"medicare",amount("200"),"employer_social_security",amount("700"),"employer_medicare",amount("200"));
  service.reviewPayroll(root.getId(),slip.getId(),new AccountingService.ReviewRequest(amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),"Verified US register",amount("0"),amount("0"),taxes));
  assertThat(salaryRow().get("us_employee_taxes")).isEqualTo(amount("2500"));assertThat(salaryRow().get("total_cost")).isEqualTo(amount("10900"));assertThat(salaryRow().get("employer_contributions")).isEqualTo(amount("900"));
  service.postPayroll(root.getId(),post("us-post"));service.postPayroll(root.getId(),post("us-retry"));assertThat(entries()).isEqualTo(1);
  assertThat(jdbc.queryForObject("SELECT sum(debit-credit) FROM public.accounting_lines l JOIN public.accounting_entries e ON e.id=l.entry_id WHERE e.company_id=?",BigDecimal.class,root.getId())).isEqualByComparingTo("0");
  assertThat(jdbc.queryForObject("SELECT sum(credit) FROM public.accounting_lines l JOIN public.accounting_entries e ON e.id=l.entry_id WHERE e.company_id=? AND account_code='US_SOCIAL_SECURITY_PAYABLE'",BigDecimal.class,root.getId())).isEqualByComparingTo("1400");
  try(var wb=new XSSFWorkbook(new ByteArrayInputStream(exports.salary(root.getId(),ym.toString(),false,null)))){var labels=new ArrayList<String>();wb.getSheet("Salary register").getRow(0).forEach(c->labels.add(c.getStringCellValue()));assertThat(labels).contains("US federal","US employer medicare").doesNotContain("TDS");}
 }
 @Test void usConfiguredMappingsReadActualSnapshotAmounts(){root.setCountry("USA");em.flush();service.mapDeduction(root.getId(),new AccountingService.MappingRequest(pf.getId(),"US_SOCIAL_SECURITY"));service.mapDeduction(root.getId(),new AccountingService.MappingRequest(tds.getId(),"US_FEDERAL"));assertThat(salaryRow().get("us_social_security")).isEqualTo(amount("2000"));assertThat(salaryRow().get("us_employer_social_security")).isEqualTo(amount("2000"));assertThat(salaryRow().get("us_federal")).isEqualTo(amount("1000"));assertThat(salaryRow().get("classified")).isEqualTo(true);}
 @Test void usTaxesCannotBeAssignedToIndia(){assertThatThrownBy(()->service.mapDeduction(root.getId(),new AccountingService.MappingRequest(pf.getId(),"US_MEDICARE"))).hasMessageContaining("US country profile");assertThatThrownBy(()->service.reviewPayroll(root.getId(),slip.getId(),new AccountingService.ReviewRequest(amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),amount("0"),"Invalid country",amount("0"),amount("0"),Map.of("federal",amount("1"))))).hasMessageContaining("US organization");}
 @Test void platformAdminCanSetCountryWithAudit(){root.setCountry(null);em.flush();companies.updateCountry(root.getId(),"India");em.flush();assertThat(root.getCountry()).isEqualTo("India");assertThat(jdbc.queryForObject("SELECT count(*) FROM public.audit_logs WHERE entity_type='Company' AND entity_id=? AND action='COUNTRY_CHANGED'",Long.class,root.getId().toString())).isEqualTo(1);}
 @Test void enterpriseAdminCannotChangeCountryThroughEitherEndpoint(){signIn("ROLE_ENTERPRISE_ADMIN");assertThatThrownBy(()->companyController.updateCountry(root.getId(),Map.of("country","United States"))).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);var request=new com.example.demo.base.dto.CompanyRequest();request.setName(root.getName());request.setCountry("United States");assertThatThrownBy(()->companies.update(root.getId(),request)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
 @Test void ordinaryCompanyUpdatePreservesCountryWhenOmitted(){signIn("ROLE_ENTERPRISE_ADMIN");var request=new com.example.demo.base.dto.CompanyRequest();request.setName(root.getName());companies.update(root.getId(),request);assertThat(root.getCountry()).isEqualTo("India");}
 @Test void salaryWorkbookUsesNumbersFormulasAndSelectedEmployees()throws Exception {
  staff.setFirstName("=1+1");em.flush();byte[] bytes=exports.salary(root.getId(),ym.toString(),false,List.of(staff.getId()));
  try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var sheet=workbook.getSheet("Salary register");assertThat(sheet.getLastRowNum()).isEqualTo(1);assertThat(sheet.getRow(1).getCell(1).getCellType()).isEqualTo(CellType.STRING);assertThat(sheet.getRow(1).getCell(11).getNumericCellValue()).isEqualTo(60000);assertThat(sheet.getRow(1).getCell(14).getNumericCellValue()).isEqualTo(2000);var summary=workbook.getSheet("Summary");assertThat(summary.getRow(1).getCell(1).getCellType()).isEqualTo(CellType.FORMULA);assertThat(workbook.getCreationHelper().createFormulaEvaluator().evaluate(summary.getRow(1).getCell(1)).getNumberValue()).isEqualTo(60000);}
 }
 @Test void ledgerWorkbookContainsJournalTrialAndProfitSheets()throws Exception {
  service.journal(root.getId(),expense("export-expense","1000"));byte[] bytes=exports.ledger(root.getId(),YearMonth.now().toString(),false);
  try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(bytes))){assertThat(workbook.getNumberOfSheets()).isEqualTo(3);assertThat(workbook.getSheet("Journal lines").getLastRowNum()).isEqualTo(2);assertThat(workbook.getSheet("Trial balance").getLastRowNum()).isEqualTo(2);}
 }
}
